#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>
#include <string>
#include "dtc-l1-common.h"
using namespace dtc_l1;
config cfg(unsigned p,unsigned n){config c;c.selected_mode=mode::PAPER_OO;c.finite_service=true;c.progressive_wakeup=false;c.tag_hash_bankrow=true;c.logical_sets=64;c.logical_ways=8;c.physical_lines=p;c.oo_pib_entries=n;c.ref_count_bits=13;c.allocation_width=4;c.tag_banks=4;c.tag_requests_per_bank_per_cycle=1;c.tag_requests_per_cycle=4;return c;}
physical_identity one(oo_frontend&f,uint64_t &t,uint64_t uid,uint64_t address){f.advance_service(t);assert(f.admit(uid));assert(f.try_serve_tag(t,address));auto r=f.access(t,uid,address);assert(r.kind==io_access_kind::NEW_MISS);f.complete(r.physical);f.advance_service(++t);assert(f.entry_ready_for(uid));assert(f.retire_ready_uid(++t,uid));++t;return r.physical;}
void sequential(unsigned p,unsigned n){oo_frontend f(cfg(p,n));uint64_t t=1;auto first=one(f,t,1,0);for(unsigned j=1;j<p+600;++j)one(f,t,j+1,uint64_t(j)*128);assert(f.occupancy()==0&&f.active_refs()==0&&f.allocated_lines()==512);assert(!f.fill_identity_matches(first));assert(f.retires()==p+600);assert(!f.retire_ready_uid(t,1));f.assert_shadow_refs();std::cout<<"{\"case\":\"sequential_replacement_generation\",\"physical\":"<<p<<",\"PIB\":"<<n<<",\"retired\":"<<f.retires()<<",\"valid_mapped_lines\":"<<f.allocated_lines()<<",\"stale_identity_rejected\":true,\"duplicate_retire_false\":true}\n";}
// Variant of merged with slot generation recorded before retirement.
void merged_checked(unsigned p,unsigned n){oo_frontend f(cfg(p,n));uint64_t t=1;physical_identity id;uint64_t oldgen=0;unsigned oldslot=0;for(unsigned i=0;i<n;++i){f.advance_service(t);assert(f.admit(i+1));if(!i){oldgen=f.entry_slot_generation(1);oldslot=f.entry_slot(1);}assert(f.try_serve_tag(t,0));auto r=f.access(t,i+1,0);assert(r.kind==(i?io_access_kind::PENDING_HIT:io_access_kind::NEW_MISS));if(!i){id=r.physical;auto again=f.access(t,1,0);assert(again.kind==io_access_kind::PENDING_HIT&&f.ref_count(id)==1);}++t;}assert(f.occupancy()==n&&f.ref_count(id)==n&&!f.admit(n+1));assert(!f.entry_ready_for(1));f.complete(id);assert(!f.entry_ready_for(1));for(unsigned i=0;i<n/4+3;++i)f.advance_service(t++);for(unsigned i=0;i<n;++i){f.advance_service(t);assert(f.entry_ready_for(i+1));assert(f.retire_ready_uid(t,i+1));assert(!f.retire_ready_uid(t,i+1));++t;}assert(!f.active_refs()&&!f.occupancy()&&f.allocated_lines()==1);assert(f.admit(10000));assert(f.entry_slot(10000)==oldslot&&f.entry_slot_generation(10000)>oldgen);f.advance_service(t);auto hit=f.access(t,10000,0);assert(hit.kind==io_access_kind::VALID_HIT&&f.ref_count(id)==1);assert(f.retire_ready_uid(++t,10000));f.assert_shadow_refs();std::cout<<"{\"case\":\"fullPIB_merge_dedup_finite_wakeup_slotgeneration\",\"physical\":"<<p<<",\"PIB\":"<<n<<",\"one_line_max_refs\":"<<n<<",\"pending_ref_count_final\":0,\"retire_width_one\":true,\"slot_generation_reuse_checked\":true}\n";}
void fullpool(unsigned p,unsigned n){oo_frontend f(cfg(p,n));uint64_t t=1;unsigned owners=p/8;std::vector<physical_identity> ids;for(unsigned i=0;i<owners;++i){assert(f.admit(i+1));for(unsigned j=0;j<8;++j){f.advance_service(t);uint64_t a=uint64_t(i*8+j)*128;assert(f.try_serve_tag(t,a));auto r=f.access(t,i+1,a);assert(r.kind==io_access_kind::NEW_MISS);ids.push_back(r.physical);++t;}}assert(f.allocated_lines()==p&&f.active_refs()==p);bool extra=f.admit(10000);if(extra){f.advance_service(t);assert(f.try_serve_tag(t,uint64_t(p)*128));auto r=f.access(t,10000,uint64_t(p)*128);assert(r.kind==io_access_kind::NO_FREE_LINE);++t;}for(auto id:ids)f.complete(id);for(unsigned j=0;j<p+4;++j)f.advance_service(t++);for(unsigned i=0;i<owners;++i){f.advance_service(t);assert(f.entry_ready_for(i+1));assert(f.retire_ready_uid(t,i+1));assert(!f.retire_ready_uid(t,i+1));++t;}assert(f.active_refs()==0&&f.allocated_lines()==512);if(!extra)assert(f.admit(10000));f.advance_service(t);auto r=f.access(t,10000,uint64_t(p)*128);assert(r.kind==io_access_kind::NEW_MISS);f.complete(r.physical);f.advance_service(++t);assert(f.retire_ready_uid(++t,10000));assert(!f.occupancy()&&!f.active_refs());f.assert_shadow_refs();std::cout<<"{\"case\":\"fullpool_pending_returns_reclaim_progress\",\"physical\":"<<p<<",\"PIB\":"<<n<<",\"fully_allocated_old_instructions\":"<<owners<<",\"one_partial_attempted\":"<<(extra?"true":"false")<<",\"old_entries_only_eligible_retire\":true,\"after_old_drain_mapped_lines\":512,\"new_reference_progressed\":true}\n";}
void quotas(){service_quota create,inject,refill,retire,collect(4);for(auto q:{&create,&inject,&refill,&retire}){assert(q->available(1));assert(q->available(1));q->commit(1);assert(!q->available(1)&&q->available(2));}service_entry a,b;a.observe_ready(1,8);b.observe_ready(1,4);assert(!a.collect(1,collect));assert(!a.collect(2,collect)&&a.sectors_left==4);assert(!b.collect(2,collect)&&b.sectors_left==4);assert(!a.collect(3,collect)&&!a.sectors_left);assert(a.collect(4,collect));assert(!b.collect(4,collect)&&!b.sectors_left);assert(b.collect(5,collect));std::cout<<"{\"case\":\"frozen_service_quotas_and_collection_edges\",\"create\":1,\"inject\":1,\"refill\":1,\"retire\":1,\"collect_32B_sectors\":4,\"tag_quota_and_writeback_throughput_not_inferred\":true}\n";}
int main(int argc,char**argv){if(argc>1){oo_frontend f(cfg(768,192));uint64_t t=1;f.advance_service(t);assert(f.admit(1));auto r=f.access(t,1,0);if(std::string(argv[1])=="duplicate_return"){f.complete(r.physical);f.complete(r.physical);return 99;}f.complete(r.physical);f.advance_service(++t);assert(f.retire_ready_uid(++t,1));++t;for(unsigned j=1;j<768+600;++j)one(f,t,j+1,uint64_t(j)*128);assert(!f.fill_identity_matches(r.physical));f.complete(r.physical);return 99;}
for(unsigned p:{640,768,1024})for(unsigned n:{128,192}){sequential(p,n);merged_checked(p,n);fullpool(p,n);}quotas();}
